resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then BASE_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BASE_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then BASE_PREMIUM end)) as BASE_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADD_ON_PREMIUM end) as ADD_ON_PREMIUM,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then NET_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then NET_PREMIUM end)) as NET_PREMIUM,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then GROSS_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROSS_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then GROSS_PREMIUM end)) as GROSS_PREMIUM,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_DISCOUNT_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROUP_DISCOUNT_AMOUNT end)) as GROUP_DISCOUNT_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then INSTALMENT_COUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTALMENT_COUNT end)) as INSTALMENT_COUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOTAL_PREMIUM_COLLECTED end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then TOTAL_PREMIUM_COLLECTED end)) as TOTAL_PREMIUM_COLLECTED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LONG_TERM_DISCOUNT_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then LONG_TERM_DISCOUNT_AMOUNT end)) as LONG_TERM_DISCOUNT_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TERRORISM_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then TERRORISM_PREMIUM end)) as TERRORISM_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_PAYMENT_STATUS end) as PREMIUM_PAYMENT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_v2' then INSTALMENT_INDICATOR end) as INSTALMENT_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ENVIRONMENT_RELIEF_FUND_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ENVIRONMENT_RELIEF_FUND_AMOUNT end)) as ENVIRONMENT_RELIEF_FUND_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then NO_CLAIM_BONUS_AMOUNT end) as NO_CLAIM_BONUS_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when BASE_PREMIUM is not null or ADD_ON_PREMIUM is not null or NET_PREMIUM is not null or GROSS_PREMIUM is not null or GROUP_DISCOUNT_AMOUNT is not null or INSTALMENT_COUNT is not null or TOTAL_PREMIUM_COLLECTED is not null or LONG_TERM_DISCOUNT_AMOUNT is not null or TERRORISM_PREMIUM is not null or PREMIUM_PAYMENT_STATUS is not null or INSTALMENT_INDICATOR is not null or ENVIRONMENT_RELIEF_FUND_AMOUNT is not null or NO_CLAIM_BONUS_AMOUNT is not null
                     then md5(upper(coalesce(cast(BASE_PREMIUM as varchar), '') || '|' || coalesce(cast(ADD_ON_PREMIUM as varchar), '') || '|' || coalesce(cast(NET_PREMIUM as varchar), '') || '|' || coalesce(cast(GROSS_PREMIUM as varchar), '') || '|' || coalesce(cast(GROUP_DISCOUNT_AMOUNT as varchar), '') || '|' || coalesce(cast(INSTALMENT_COUNT as varchar), '') || '|' || coalesce(cast(TOTAL_PREMIUM_COLLECTED as varchar), '') || '|' || coalesce(cast(LONG_TERM_DISCOUNT_AMOUNT as varchar), '') || '|' || coalesce(cast(TERRORISM_PREMIUM as varchar), '') || '|' || coalesce(cast(PREMIUM_PAYMENT_STATUS as varchar), '') || '|' || coalesce(cast(INSTALMENT_INDICATOR as varchar), '') || '|' || coalesce(cast(ENVIRONMENT_RELIEF_FUND_AMOUNT as varchar), '') || '|' || coalesce(cast(NO_CLAIM_BONUS_AMOUNT as varchar), '')))
                end as SAT_POLICY_PREMIUM_SUMMARY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_PREMIUM_SUMMARY_HASHDIFF is not null
